#include <algorithm>
#include <cstddef>
#include <string>
#include <vector>

struct Teacher
{
    std::string name{};
};

class Department
{
public:
    void add(Teacher& teacher)
    {
        if (!has(teacher))
        {
            m_teachers.push_back(&teacher);
        }
    }

    std::size_t size() const { return m_teachers.size(); }

    bool has(const Teacher& teacher) const
    {
        return std::find(m_teachers.begin(), m_teachers.end(), &teacher) != m_teachers.end();
    }

    std::string names() const
    {
        std::string result{};
        for (const Teacher* teacher : m_teachers)
        {
            if (!result.empty())
            {
                result += ", ";
            }
            result += teacher->name;
        }
        return result;
    }

private:
    std::vector<const Teacher*> m_teachers{};
};

unitTests:
TEST("adding teachers") { Teacher ann{ "Ann" }, bob{ "Bob" }; Department d{}; d.add(ann); d.add(bob); CHECK_EQ(d.size(), 2u); CHECK(d.has(ann)); CHECK_EQ(d.names(), "Ann, Bob"); }
TEST("no duplicates") { Teacher ann{ "Ann" }; Department d{}; d.add(ann); d.add(ann); CHECK_EQ(d.size(), 1u); }
TEST("the department sees the real teacher, not a copy") { Teacher ann{ "Ann" }; Department d{}; d.add(ann); ann.name = "Dr Ann"; CHECK_EQ(d.names(), "Dr Ann"); }
TEST("teachers outlive the department") { Teacher ann{ "Ann" }; { Department d{}; d.add(ann); } CHECK_EQ(ann.name, "Ann"); }
TEST("two teachers with the same name are different people") { Teacher a{ "Sam" }, b{ "Sam" }; Department d{}; d.add(a); CHECK(!d.has(b)); }

